      }
    ],
    "solution": {
      "brute_force": {
        "approach": "Check all O(n^2) substrings. For each substring, count its distinct characters using a set. If the count is at most k, update the maximum length. This is O(n^2) time and does not scale for large inputs.",
        "code": "def longest_window_k_distinct(log: str, k: int) -> int:\n    if k == 0 or not log:\n        return 0\n\n    n = len(log)\n    max_len = 0\n\n    for i in range(n):\n        seen = set()\n        for j in range(i, n):\n            seen.add(log[j])\n            if len(seen) > k:\n                break           # adding more chars won't reduce distinct count\n            max_len = max(max_len, j - i + 1)\n\n    return max_len",
        "time": "O(n^2)",
